"""Generated bytes have a durable owner before their actual disk thread starts."""

import asyncio
import threading
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from pathlib import Path
from uuid import UUID

import pytest
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncEngine, AsyncSession

from src.core.config import settings
from src.core.exceptions import BaseAPIException
from src.domains.attachments.file_contracts import UploadMetadata
from src.domains.attachments.generated_publication import publish_generated_files
from src.domains.attachments.models import Attachment, AttachmentOrigin, AttachmentStatus
from src.domains.document_generation import service
from src.domains.users.account_cleanup import refuse_account_writers
from tests.helpers.committed_users import commit_owner

pytestmark = pytest.mark.integration


async def test_cancelled_generated_file_keeps_its_intent_until_the_real_thread_stops(
    async_engine: AsyncEngine,
    committed_user_ids: list[UUID],
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    owner = await commit_owner(async_engine, committed_user_ids)
    started, release = threading.Event(), threading.Event()
    original_write = Path.write_bytes

    def delayed(path: Path, data: bytes) -> int:
        started.set()
        assert release.wait(15)
        return original_write(path, data)

    @asynccontextmanager
    async def session() -> AsyncIterator[AsyncSession]:
        async with AsyncSession(async_engine, expire_on_commit=False) as db:
            yield db
            await db.commit()

    monkeypatch.setattr(settings, "attachments_storage_path", str(tmp_path))
    monkeypatch.setattr(service, "get_db_context", session)
    monkeypatch.setattr(Path, "write_bytes", delayed)
    task = asyncio.create_task(
        service.store_document(
            user_id=owner,
            conversation_id=None,
            data=b"generated bytes",
            stem="controlled",
            extension="txt",
            mime_type="text/plain",
        )
    )
    try:
        assert await asyncio.to_thread(started.wait, 10)
        async with AsyncSession(async_engine) as db:
            with pytest.raises(BaseAPIException):
                await refuse_account_writers(db, owner)
        task.cancel()
        await asyncio.sleep(0)
        task.cancel()
        assert not task.done()
        release.set()
        with pytest.raises(asyncio.CancelledError):
            await task
        async with AsyncSession(async_engine) as db:
            row = await db.scalar(select(Attachment).where(Attachment.user_id == owner))
            assert row is not None and row.status == AttachmentStatus.DELETING
            assert row.file_path and (tmp_path / row.file_path).exists()
            await refuse_account_writers(db, owner)
    finally:
        release.set()
        await asyncio.gather(task, return_exceptions=True)


async def test_failed_generated_batch_keeps_all_paths_and_publishes_no_partial_result(
    async_engine: AsyncEngine,
    committed_user_ids: list[UUID],
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    owner = await commit_owner(async_engine, committed_user_ids)
    monkeypatch.setattr(settings, "attachments_storage_path", str(tmp_path))
    original = Path.write_bytes
    calls: list[Path] = []

    def failing(path: Path, data: bytes) -> int:
        calls.append(path)
        if len(calls) == 2:
            raise OSError("Injected second file failure")
        return original(path, data)

    monkeypatch.setattr(Path, "write_bytes", failing)
    files = [
        (
            UploadMetadata(
                f"file-{index}.txt",
                "text/plain",
                "document",
                ".txt",
                origin=AttachmentOrigin.GENERATED_DOCUMENT,
            ),
            b"controlled",
        )
        for index in range(2)
    ]
    async with AsyncSession(async_engine, expire_on_commit=False) as db:
        with pytest.raises(OSError):
            await publish_generated_files(db, owner_id=owner, files=files)
        rows = list(await db.scalars(select(Attachment).where(Attachment.user_id == owner)))
        assert len(rows) == 2
        assert all(row.status == AttachmentStatus.DELETING for row in rows)
        assert all(row.origin == AttachmentOrigin.GENERATED_DOCUMENT.value for row in rows)
        assert len(list(tmp_path.rglob("*.txt"))) == 1
